import Ajv from "ajv";
interface Contribution {
  extensionPoint?: string;
  contribution?: any;
  nls?: any;
  [key: string]: any;
}

const omit = <T extends object, K extends keyof T>(
  obj: T,
  ...keys: K[]
): Omit<T, K> => {
  const entries = Object.entries(obj).filter(([k]) => !keys.includes(k as K));
  return Object.fromEntries(entries) as Omit<T, K>;
};

const reduce = <T, U>(
  collection: T[] | Record<string, T>,
  iteratee: (
    acc: U,
    value: T,
    key: string | number,
    src: typeof collection
  ) => U,
  init: U
): U => {
  if (Array.isArray(collection)) {
    return collection.reduce<U>(
      (acc, val, i) => iteratee(acc, val, i, collection),
      init
    );
  }
  return Object.entries(collection).reduce<U>(
    (acc, [key, val]) => iteratee(acc, val as T, key, collection),
    init
  );
};

const filter = <T>(
  collection: T[] | Record<string, T>,
  predicate: (val: T, key: string | number, src: typeof collection) => boolean
): T[] => {
  if (Array.isArray(collection)) {
    return collection.filter((val, i) => predicate(val, i, collection));
  }
  return Object.entries(collection)
    .filter(([k, v]) => predicate(v as T, k, collection))
    .map(([_, v]) => v as T);
};

const isObject = (val: unknown): val is object =>
  val !== null && (typeof val === "object" || typeof val === "function");

const flatten = <T>(arr: any[], shallow = false): T[] =>
  shallow ? arr.flat() : arr.flat(Infinity);

const memoize = <F extends (...args: any[]) => any>(fn: F): F => {
  const cache = new Map<string, ReturnType<F>>();
  return function (this: any, ...args: any[]) {
    const key = JSON.stringify(args);
    if (!cache.has(key)) {
      cache.set(key, fn.apply(this, args));
    }
    return cache.get(key)!;
  } as F;
};

const forEach = <T>(
  collection: T[] | Record<string, T>,
  iteratee: (val: T, key: string | number, src: typeof collection) => void
): void => {
  if (Array.isArray(collection)) {
    collection.forEach((val, i) => iteratee(val, i, collection));
  } else {
    Object.entries(collection).forEach(([key, val]) =>
      iteratee(val as T, key, collection)
    );
  }
};

import internationalize from "./internationalize";
import pluginSchema from "./plugin.schema.json";

const disableEval = false;

function validateSchema(ajv, schema) {
  let errorMessage = null;
  try {
    ajv.validateSchema(schema);
    if (ajv.errors) errorMessage = ajv.errorsText();
  } catch (e) {
    errorMessage = e.message;
  }
  return errorMessage;
}

//
// For each plugin, add the schema types defined under the
// "schemaDefinitions" key in its ui-config to the master schema.
// Types defined in schemaDefinitions can be referenced in other
// types defined in extensionPoints and other schemaDefinitions,
// via { "$ref": "definingPluginId/schemaDefinitions#/someType"}
//
function appendValidSchemaDefinitions(ajv, pluginConfigs) {
  pluginConfigs.forEach((config) => {
    const validTypes = reduce(
      config.schemaDefinitions || {},
      (res, typeSchema, typeName) => {
        const errorMessage = validateSchema(ajv, typeSchema);
        if (errorMessage) {
          // eslint-disable-next-line
          console.error(
            // NOSONAR
            "Invalid schemaDefinition '%s' in plugin '%s':\n %s",
            typeName,
            config.pluginId,
            errorMessage
          );
        } else {
          res[typeName] = typeSchema;
        }
        return res;
      },
      {}
    );
    if (Object.keys(validTypes).length) {
      if (!disableEval) {
        ajv.addSchema(
          config.schemaDefinitions,
          `${config.pluginId}/schemaDefinitions`
        );
      }
    }
  });
}

function validateExtensionPointDef(
  ajv,
  pluginId,
  extensionPointId,
  extensionSchema
) {
  const errorMessage = disableEval
    ? false
    : validateSchema(ajv, extensionSchema);
  if (errorMessage) {
    // eslint-disable-next-line
    console.error(
      // NOSONAR
      "Invalid extension point definition '%s/%s':\n %s\nDefinition:\n%o",
      pluginId,
      extensionPointId,
      errorMessage,
      extensionSchema
    );
  }
  return !errorMessage;
}

function validateContribution(
  ajv,
  extensionPointDef,
  extensionPointName,
  receivingPluginId,
  contribution: Contribution,
  sourcePluginId
) {
  // TODO: extensionPointDefs can fail to compile if they
  // have unresolvable $refs, crashing the indexing process
  if (!disableEval) {
    const validate = ajv.compile(extensionPointDef);
    validate(omit(contribution, "extensionPoint", "requiredPermissions"));
    if (validate.errors) {
      // eslint-disable-next-line
      console.error(
        // NOSONAR
        "Invalid contribution from '%s' to '%s/%s':\n'%s'\nContribution data:\n%o",
        sourcePluginId,
        receivingPluginId,
        extensionPointName || contribution.extensionPoint,
        ajv.errorsText(validate.errors),
        contribution
      );
      return false;
    }
  }
  return true;
}

function validExtensionPointDefs(ajv, pluginConfig) {
  const { pluginId } = pluginConfig;
  return reduce(
    pluginConfig.extensionPoints,
    (res, extensionSchema, extensionPointId) => {
      if (
        validateExtensionPointDef(
          ajv,
          pluginId,
          extensionPointId,
          extensionSchema
        )
      ) {
        res[extensionPointId] = extensionSchema;
      }
      return res;
    },
    {}
  );
}

function validContributions(
  ajv,
  receivingPlugin,
  extensionPointName,
  sourcePluginId,
  contributions
) {
  return filter(contributions, (contribution) => {
    if (!isObject(contribution)) {
      // eslint-disable-next-line no-console
      console.error(
        "Invalid contribution data '%s'",
        JSON.stringify(contribution)
      ); // NOSONAR
      return false;
    }
    const extensionPointDef =
      receivingPlugin.extensionPoints[
        extensionPointName || (contribution as Contribution).extensionPoint
      ];
    if (extensionPointDef) {
      // the extension schema may be empty, in which case
      // we don't attempt to validate anything
      return Object.keys(extensionPointDef).length
        ? validateContribution(
            ajv,
            extensionPointDef,
            extensionPointName,
            receivingPlugin.pluginId,
            contribution,
            sourcePluginId
          )
        : true;
    }
    // eslint-disable-next-line no-console
    console.warn(
      // NOSONAR
      "Plugin '%s' contributes to an undefined extension point '%s' in plugin '%s'",
      sourcePluginId,
      extensionPointName,
      receivingPlugin.pluginId
    );
    return true;
  });
}

function getTargetData(target) {
  const [receivingPluginId, extensionPointName] = target.split("/");
  return { receivingPluginId, extensionPointName };
}

function appendContributionData(ajv, pluginConfigs, index) {
  pluginConfigs.forEach((config) => {
    const pluginFilter = config.$filter;
    forEach(config.contributions || {}, (contribs, target) => {
      const { receivingPluginId, extensionPointName } = getTargetData(target);
      const receivingPlugin = index[receivingPluginId];
      if (receivingPlugin) {
        validContributions(
          ajv,
          receivingPlugin,
          extensionPointName,
          config.pluginId,
          flatten([contribs || []])
        ).forEach((contribution) => {
          if (extensionPointName)
            (contribution as Contribution).extensionPoint = extensionPointName;
          if (
            pluginFilter &&
            !(contribution as Contribution).hasOwnProperty("$filter")
          ) {
            (contribution as Contribution).$filter = pluginFilter;
          }
          const contrib = { sourcePluginId: config.pluginId };
          Object.defineProperty(contrib, "contribution", {
            enumerable: true,
            get: memoize(
              internationalize.bind(
                null,
                contribution,
                config,
                "en" /*window._i18n.locale*/
              )
            ),
          });
          receivingPlugin.contributions.push(contrib);
        });
      } else {
        // eslint-disable-next-line no-console
        console.warn(
          // NOSONAR
          "Plugin '%s' contributes to an unknown plugin id '%s'",
          config.pluginId,
          receivingPluginId
        );
      }
    });
  });
}

export function buildContributionIndex(pluginConfigs) {
  const ajv = new Ajv();
  if (!disableEval) {
    ajv.addSchema(pluginSchema);
  }
  appendValidSchemaDefinitions(ajv, pluginConfigs);
  const index = {};
  pluginConfigs.forEach((config) => {
    index[config.pluginId] = {
      pluginId: config.pluginId,
      baseUrl: config.baseUrl,
      modulePreload: config.modulePreload || {},
      extensionPoints: validExtensionPointDefs(ajv, config || {}),
      contributions: [],
      title: config.title || "",
    };
  });
  appendContributionData(ajv, pluginConfigs, index);
  return index;
}
